/* Scroll reveal */
(function () {
  var nodes = document.querySelectorAll('.reveal');
  if (!('IntersectionObserver' in window)) {
    nodes.forEach(function (n) { n.classList.add('visible'); });
    return;
  }
  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        io.unobserve(entry.target);
      }
    });
  }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
  nodes.forEach(function (n) { io.observe(n); });
})();

/* Sticky WhatsApp after hero */
(function () {
  var btn = document.getElementById('whatsapp-float');
  var hero = document.getElementById('hero');
  if (!btn || !hero) return;
  var ticking = false;
  function update() {
    ticking = false;
    var bottom = hero.offsetTop + hero.offsetHeight;
    btn.classList.toggle('show', window.scrollY > bottom - 80);
  }
  function onScroll() {
    if (!ticking) {
      ticking = true;
      window.requestAnimationFrame(update);
    }
  }
  window.addEventListener('scroll', onScroll, { passive: true });
  update();
})();

/* FAQ */
(function () {
  var items = document.querySelectorAll('.faq-item');
  items.forEach(function (item) {
    var trigger = item.querySelector('.faq-trigger');
    if (!trigger) return;
    trigger.addEventListener('click', function () {
      var isOpen = item.classList.contains('open');
      items.forEach(function (other) {
        other.classList.remove('open');
        var t = other.querySelector('.faq-trigger');
        if (t) t.setAttribute('aria-expanded', 'false');
      });
      if (!isOpen) {
        item.classList.add('open');
        trigger.setAttribute('aria-expanded', 'true');
      }
    });
  });
})();

/* Forms → Google Sheet, then generate_lead (no WhatsApp redirect) */
(function () {
  var GAS_URL = 'https://script.google.com/macros/s/AKfycbzTo3v4gxY1FmMrSFndbYSDaWRhjL58uUzkicjfDW7xS1xdoL_Rxsq69juo2PcT3g2q_Q/exec';

  /* Distinct page_type per form, sent with the lead and with generate_lead */
  var PAGE_TYPE_BY_FORM = {
    'hero-form': 'home',
    'hero-form-mobile': 'home',
    'enquiry-form': 'home',
    'hp-sidebar-form': 'hospital_detail'
  };

  function field(form, names) {
    for (var i = 0; i < names.length; i++) {
      var el = form.elements.namedItem(names[i]);
      if (el && el.value) return String(el.value).trim();
    }
    return '';
  }

  function getLeadPayload(form, pageType) {
    return {
      name: field(form, ['name']),
      email: field(form, ['email']),
      whatsapp: field(form, ['whatsapp', 'phone']),
      country: field(form, ['country']),
      condition: field(form, ['condition', 'message']),
      page_type: pageType,
      form_id: form.id || ''
    };
  }

  function showFormError(form, message) {
    var el = form.querySelector('.form-submit-error');
    if (!el) {
      el = document.createElement('p');
      el.className = 'form-submit-error text-center text-sm font-semibold mt-3';
      el.style.color = '#DC2626';
      form.appendChild(el);
    }
    el.textContent = message;
    el.hidden = false;
  }

  function clearFormError(form) {
    var el = form.querySelector('.form-submit-error');
    if (el) {
      el.textContent = '';
      el.hidden = true;
    }
  }

  function setSubmitting(form, isSubmitting) {
    var btn = form.querySelector('[type="submit"]');
    if (btn) btn.disabled = !!isSubmitting;
  }

  function submitLeadToSheet(payload) {
    var body = JSON.stringify(payload);
    var qs =
      'name=' + encodeURIComponent(payload.name || '') +
      '&email=' + encodeURIComponent(payload.email || '') +
      '&whatsapp=' + encodeURIComponent(payload.whatsapp || '') +
      '&country=' + encodeURIComponent(payload.country || '') +
      '&condition=' + encodeURIComponent(payload.condition || '') +
      '&page_type=' + encodeURIComponent(payload.page_type || '');

    return new Promise(function (resolve, reject) {
      var xhr = new XMLHttpRequest();
      xhr.open('POST', GAS_URL + '?' + qs);
      xhr.setRequestHeader('Content-Type', 'text/plain;charset=utf-8');
      xhr.onload = function () {
        if (xhr.status < 200 || xhr.status >= 300) {
          reject(new Error('Sheet HTTP ' + xhr.status));
          return;
        }
        var data;
        try {
          data = JSON.parse(xhr.responseText);
        } catch (err) {
          reject(new Error('Invalid sheet response'));
          return;
        }
        if (!data || data.success !== true) {
          reject(new Error('Sheet did not confirm save'));
          return;
        }
        resolve(data);
      };
      xhr.onerror = function () {
        reject(new Error('Sheet network error'));
      };
      xhr.send(body);
    });
  }

  /* Fires only after the Sheet POST succeeds - for GTM + GA4 → Google Ads */
  function fireGenerateLead(payload) {
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push({
      event: 'generate_lead',
      form_id: payload.form_id,
      lead_source: 'website_form',
      page_type: payload.page_type
    });

    if (typeof window.gtag !== 'function') {
      window.gtag = function () {
        window.dataLayer.push(arguments);
      };
    }

    /* GA4 event (imported in Google Ads as Primary: VaidTrack.com generate_lead) */
    window.gtag('event', 'generate_lead', {
      send_to: 'G-5TBH8QQ2EQ',
      form_id: payload.form_id,
      lead_source: 'website_form',
      page_type: payload.page_type
    });
  }

  function wireLeadForm(formId, onSuccess) {
    var form = document.getElementById(formId);
    if (!form) return;
    var pageType = PAGE_TYPE_BY_FORM[formId] || 'unknown';

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      clearFormError(form);

      if (!form.checkValidity()) {
        form.reportValidity();
        return;
      }

      var payload = getLeadPayload(form, pageType);
      setSubmitting(form, true);

      submitLeadToSheet(payload)
        .then(function () {
          fireGenerateLead(payload);
          if (typeof onSuccess === 'function') onSuccess(form);
        })
        .catch(function () {
          showFormError(form, 'Something went wrong, please try again or WhatsApp us directly.');
        })
        .then(function () {
          setSubmitting(form, false);
        });
    });
  }

  wireLeadForm('hero-form', function (form) {
    form.classList.add('hidden');
    var success = document.getElementById('hero-form-success');
    if (success) success.classList.remove('hidden');
  });

  wireLeadForm('hero-form-mobile', function (form) {
    form.classList.add('hidden');
    var success = document.getElementById('hero-form-mobile-success');
    if (success) success.classList.remove('hidden');
  });

  wireLeadForm('enquiry-form', function () {
    var panel = document.getElementById('form-panel');
    var success = document.getElementById('form-success');
    if (panel) panel.classList.add('hidden');
    if (success) success.classList.remove('hidden');
  });

  wireLeadForm('hp-sidebar-form', function (form) {
    form.classList.add('hidden');
    var success = document.getElementById('hp-sidebar-form-success');
    if (success) success.classList.remove('hidden');
  });
})();

/* Mobile appointment form popup */
(function () {
  var modal = document.getElementById('appointment-modal');
  if (!modal) return;

  var openBtn = document.getElementById('open-appointment-modal');
  var mq = window.matchMedia('(max-width: 1023px)');
  var lastFocus = null;

  function isResponsive() {
    return mq.matches;
  }

  function showModal() {
    lastFocus = document.activeElement;
    modal.hidden = false;
    modal.setAttribute('aria-hidden', 'false');
    document.body.classList.add('appt-modal-open');
    var first = modal.querySelector('input, textarea, button');
    if (first) setTimeout(function () { first.focus(); }, 50);
  }

  function openModal() {
    if (!isResponsive()) return;
    showModal();
  }

  function closeModal() {
    modal.hidden = true;
    modal.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('appt-modal-open');
    if (lastFocus && lastFocus.focus) lastFocus.focus();
  }

  window.openAppointmentModal = openModal;
  window.closeAppointmentModal = closeModal;

  if (openBtn) {
    openBtn.addEventListener('click', function (e) {
      e.preventDefault();
      showModal();
    });
  }

  modal.addEventListener('click', function (e) {
    if (e.target.closest && e.target.closest('[data-appt-close]')) {
      closeModal();
    }
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && !modal.hidden) closeModal();
  });

  var planTravelBtn = document.getElementById('hiw-plan-travel');
  if (planTravelBtn) {
    planTravelBtn.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopImmediatePropagation();
      showModal();
    });
  }

  var bottomBook = document.querySelector('.mobile-bottom-book');
  if (bottomBook) {
    bottomBook.addEventListener('click', function (e) {
      if (!isResponsive()) return;
      e.preventDefault();
      openModal();
    });
  }
})();

/* Clean section URLs: /treatment → scroll to #treatment (no hash in address bar) */
(function () {
  var SECTION_PATHS = {
    treatment: 'treatment',
    doctors: 'doctors',
    testimonials: 'testimonials',
    'about-us': 'about-us',
    faq: 'faq',
    contact: 'contact',
    'book-appointment': 'book-appointment',
    'visa-travel': 'how-it-works',
    'how-it-works': 'how-it-works'
  };

  function pathToSection(pathname) {
    var seg = (pathname || '').replace(/\/+$/, '').split('/').pop() || '';
    return SECTION_PATHS[seg] || null;
  }

  function scrollToId(id, behavior) {
    var el = document.getElementById(id);
    if (!el) return false;
    el.scrollIntoView({ behavior: behavior || 'smooth', block: 'start' });
    return true;
  }

  function goSection(id, push) {
    if (id === 'book-appointment' && window.matchMedia('(max-width: 1023px)').matches) {
      if (typeof window.openAppointmentModal === 'function') {
        window.openAppointmentModal();
      }
      if (push && window.history && history.pushState) {
        history.pushState({ section: id }, '', '/' + id);
      }
      return;
    }
    if (!scrollToId(id, 'smooth')) return;
    if (push && window.history && history.pushState) {
      history.pushState({ section: id }, '', '/' + id);
    }
  }

  /* Legacy /#treatment â†’ /treatment */
  if (location.hash && location.hash.length > 1) {
    var hashId = location.hash.slice(1);
    if (SECTION_PATHS[hashId] && document.getElementById(hashId)) {
      if (history.replaceState) {
        history.replaceState({ section: hashId }, '', '/' + hashId);
      }
      setTimeout(function () { scrollToId(hashId, 'auto'); }, 0);
    }
  } else {
    var fromPath = pathToSection(location.pathname);
    /* Note: book-appointment is intentionally excluded here - it's a
       modal trigger, not a page, so landing on/refreshing this path
       must never auto-open the popup without an explicit click. */
    if (fromPath && fromPath !== 'book-appointment') {
      setTimeout(function () { scrollToId(fromPath, 'auto'); }, 50);
    }
  }

  document.addEventListener('click', function (e) {
    var a = e.target.closest && e.target.closest('a[href]');
    if (!a) return;
    var href = a.getAttribute('href');
    if (!href) return;

    var id = null;
    if (href.charAt(0) === '/' && href.indexOf('#') === -1 && href.indexOf('?') === -1) {
      id = pathToSection(href);
    }
    if (!id) return;
    if (!document.getElementById(id)) return;

    e.preventDefault();
    goSection(id, true);
  });

  window.addEventListener('popstate', function () {
    var id = pathToSection(location.pathname);
    if (id) scrollToId(id, 'smooth');
    else if (location.pathname === '/' || location.pathname === '') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  });
})();

/* YouTube click-to-play facades */
(function () {
  function activate(btn) {
    var id = btn.getAttribute('data-youtube-id');
    if (!id) return;
    var title = btn.getAttribute('aria-label') || 'Patient story video';
    var start = btn.getAttribute('data-youtube-start');
    var startParam = start && /^\d+$/.test(start) ? '&start=' + start : '';
    var iframe = document.createElement('iframe');
    iframe.className = 'w-full h-full';
    iframe.src = 'https://www.youtube-nocookie.com/embed/' + encodeURIComponent(id) + '?autoplay=1&rel=0' + startParam;
    iframe.title = title;
    iframe.allow = 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';
    iframe.setAttribute('allowfullscreen', '');
    iframe.setAttribute('referrerpolicy', 'strict-origin-when-cross-origin');
    btn.replaceWith(iframe);
  }

  document.addEventListener('click', function (e) {
    var btn = e.target.closest && e.target.closest('.yt-facade');
    if (!btn) return;
    e.preventDefault();
    activate(btn);
  });
})();
